import { injectable } from 'inversify';
import { ILocationRepository } from '@src/domain/interfaces/location';
import { Location } from '@src/domain/entities/location';
import { HttpService } from '@core/service';
import { GEOCODING_BASE_URL } from '@src/config';

@injectable()
export class LocationRepository
  extends HttpService
  implements ILocationRepository
{
  constructor() {
    super({ baseURL: GEOCODING_BASE_URL });
  }
  async getLocation(name: string): Promise<Location> {
    const url = '/v1/search';

    const response = await this.get<{ results: Location[] }>(url, {
      params: { name },
    });

    return this.parseLocation(response?.data?.results[0]);
  }

  private parseLocation(data: any): Location {
    return {
      id: String(data.id || ''),
      name: String(data.name || ''),
      latitude: Number(data.latitude),
      longitude: Number(data.longitude),
      country: String(data.country || ''),
    };
  }
}
