import { View, Dimensions } from 'react-native';
import React, { useEffect, useRef } from 'react';
import { BottomSheet, BottomSheetManager, GradientButton, useTheme, Spacer, IS_IOS, BottomSheetRef } from '@core/ui';
import PdfViewer from '../pdf/Pdf';
import useCSS from '@src/presentation/style';
import RNFS from 'react-native-fs';
import Share from 'react-native-share';
import { copyFileToDownloadFolder, getFileName, useTranslation } from '@core/service';
import { ScrollView } from 'react-native-gesture-handler';

const windowWidth = Dimensions.get('window').width;

type Props = {
    show: boolean;
    title: string;
    onClose?: () => void;
    link: string;
    showButton?: boolean
};
export default function BottomSheetPDF({ show, title, onClose, link, showButton = true }: Props) {
    const bsRef = useRef<BottomSheetRef>(null);
    const { theme } = useTheme();
    const css = useCSS();
    const { t } = useTranslation(['common']);

    const onDownload = async () => {
        try {
            if (link) {
                const fileName = getFileName(link);
                const tempPath = `${RNFS.TemporaryDirectoryPath}/${fileName}`;
                const downloadOptions = {
                    fromUrl: link,
                    toFile: tempPath,
                };

                await RNFS.downloadFile(downloadOptions).promise;

                const filePath = IS_IOS ? tempPath : `file://${tempPath}`;
                if (!IS_IOS) {
                    await copyFileToDownloadFolder(filePath);
                }

                const shareOptions = {
                    title: 'download pdf', //t('share'),
                    url: filePath,
                };
                await Share.open(shareOptions);
            } else {
                // console.log('error');
            }
        } catch (error) { }
    };

    const handleDownload = () => {
        onDownload();
        bsRef.current?.close();
    };

    const onShowModal = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet ref={bsRef} id={portalId} title={title} description='' onClose={onClose} enableContentPanningGesture={false}>
                    <View style={[css.bg_neutral_200]}>
                        <ScrollView>
                            <PdfViewer
                                source={{
                                    uri: link,
                                    cache: true,
                                }}
                                style={{ width: windowWidth - theme.Size.hs(32), aspectRatio: 1 / 1.414 }}
                            />
                        </ScrollView>
                    </View>
                    <Spacer height={16} />
                    {showButton &&
                        <GradientButton gradientProps={{ type: 'primary' }} title={t('download')} onPress={handleDownload} />
                    }
                </BottomSheet>
            ),
        });
    };

    useEffect(() => {
        if (show) {
            onShowModal();
        }
    }, [show]);
    return <View></View>;
}
