export const fetchGetInitLoanProposal = createAsyncThunk('get_init_loan_proposal/fetch', async (request: GetInitLoanProposalPayload['data']) => {
    const getInitLoanProposal = container.get<GetInitLoanProposalHandler>(TYPES.GetInitLoanProposalHandler);
    const payload = {
        ...payloadConfig,
        data: request,
    };
    return await getInitLoanProposal.handle(payload);
});

