export const fetchGenerateContract = createAsyncThunk('generate_contract/fetch', async (request: GenerateContractPayload['data']) => {
    const payload = {
        ...payloadConfig,
        data: request,
    };
    const generateContract = container.get<GenerateContractHandler>(TYPES.GenerateContractHandler);
    const res = await generateContract.handle(payload);
    return res;
});

export const fetchInitLoanProposal = createAsyncThunk('init_loan_proposal/fetch', async (request: InitLoanProposalPayload['data'], thunkApi) => {
    try {
        const initLoanProposal = container.get<InitLoanProposalHandler>(TYPES.InitLoanProposalHandler);
        const payload = {
            ...payloadConfig,
            data: request,
        };

        return await initLoanProposal.handle(payload);
    } catch (error) {
        return thunkApi.rejectWithValue(error);
    }
});

